import { useAuth0 } from "@auth0/auth0-react";
import { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import CircularProgress from "@mui/material/CircularProgress";
import axios from "axios";

export default function Callback() {
  const { isAuthenticated, isLoading, user, error } = useAuth0();
  const navigate = useNavigate();
  
  useEffect(() => {
    if (isLoading) return;          // wait for Auth0 to finish
    if (!isAuthenticated || !user) return;

    saveUser(user)
      .then(() => navigate("/prompt"))
      .catch(() => navigate("/login"));
  }, [isLoading, isAuthenticated, user, navigate]);

  if (isLoading) return <CircularProgress size={40} />;
  if (error) return <p>Login failed.</p>;

  return null;
}

const API_URL = process.env.REACT_APP_API_URL;
async function saveUser(user) {
  const userData = {
      auth0Id: user.sub,
      email: user.email,
      emailVerified: user.email_verified,
      nickname: user.nickname,
      name: user.name,
      imageUrl: user.picture,
      updatedAt: user.updated_at
    };

  await axios.post(
    `${API_URL}/api/users`, 
    userData, 
    {headers: { Authorization: `Bearer ${await useAccessToken(process.env.REACT_APP_JWT_AUDIENCE)}` }} 
  );
}

async function useAccessToken(audience) {
  const { getAccessTokenSilently } = useAuth0();
  const [token, setToken] = useState(null);

  useEffect(() => {
    const fetchToken = async () => {
      const t = await getAccessTokenSilently({ audience });
      setToken(t);
    };
    fetchToken();
  }, [audience, getAccessTokenSilently]);

  return token;
}
